   451→	 * 다나와 관리모듈에 맞는 형식으로 제작
   452→	 */
   453→	public static void analyzeTextDetail(NodeClient client, String text, TokenStream stream, String index,
   454→		Map<String, List<List<String>>> result, Map<String, Boolean> synonymWayMap, Map<String, List<String>> synonymMap, boolean useForQuery) {
   455→		CharTermAttribute termAttr = stream.addAttribute(CharTermAttribute.class);
   456→		TypeAttribute typeAttr = stream.addAttribute(TypeAttribute.class);
   457→		ExtraTermAttribute extAttr = stream.addAttribute(ExtraTermAttribute.class);
   458→		SynonymAttribute synAttr = stream.addAttribute(SynonymAttribute.class);
   459→		OffsetAttribute offAttr = stream.addAttribute(OffsetAttribute.class);
   460→		List<List<String>> wordList = null;
   461→		List<String> words = null;
   462→		List<String> words2 = null;
   463→		List<CharSequence> synonyms = synAttr.getSynonyms();
   464→		List<String> tempTermList = new ArrayList<>();
   465→		for (String key : ANALYSIS_RESULT_LABELS.keySet()) {
   466→			result.put(key, new ArrayList<>());
   467→		}
   468→
   469→		String term = null;
   470→		String type = null;
   471→		String setName = null;
   472→		String setNamePrev = null;
   473→		int[] offset = { 0, 0 };
   474→		int[] offsetPrev = { 0, 0 };
   475→		boolean oneWaySynonym = false;
   476→
   477→		// 2개 초과의 텀에 대해 유사어 확장
   478→		// 이전 텀, 이전 이전텀
   479→		String prevTerm = null;
   480→		String prePrevTerm = null;
   481→		ProductNameDictionary dictionary = getDictionary();
   482→		SynonymDictionary synonymDict = dictionary.getDictionary(ProductNameDictionary.DICT_SYNONYM, SynonymDictionary.class);
   483→
   484→		try {
   485→			stream.reset();
   486→			while (stream.incrementToken()) {
   487→				setNamePrev = setName;
   488→				offsetPrev = new int[] { offset[0], offset[1] };
   489→				term = String.valueOf(termAttr);
   490→				type = typeAttr.type();
   491→				offset = new int[] { offAttr.startOffset(), offAttr.endOffset() };
   492→				logger.trace("TERM:{} / {}", term, type);
   493→				if (!ANALYZE_SET_FULL_STRING.equals(setNamePrev) && offset[0] < offsetPrev[1]) {
   494→					// 모델명 / 단위명 등 뒤에 나온 부속단어 (색인시)
   495→					wordList = result.get(setNamePrev);
   496→					if (wordList != null) {
   497→						words = wordList.get(wordList.size() - 1);
   498→						words.add(term);
   499→						setName = setNamePrev;
   500→						offset = new int[] { offsetPrev[0], offsetPrev[1] };
   501→						setAnalyzedResult(result, term, ANALYZE_SET_NORMAL, ANALYZE_SET_FINAL);
   502→					}
   503→				} else if (ProductNameTokenizer.FULL_STRING.equals(type)) {
   504→					// 전체 단어
   505→					setName = ANALYZE_SET_FULL_STRING;
   506→					setAnalyzedResult(result, term, ANALYZE_SET_FULL_STRING, ANALYZE_SET_FINAL);
   507→				} else if (ProductNameTokenizer.MODEL_NAME.equals(type)) {
   508→					// 모델명의 경우 색인시와 질의시 추출방법이 서로 다르다.
   509→					setName = ANALYZE_SET_MODEL_NAME;
   510→					setAnalyzedResult(result, term, ANALYZE_SET_MODEL_NAME, ANALYZE_SET_NORMAL, ANALYZE_SET_FINAL);
   511→				} else if (ProductNameTokenizer.UNIT.equals(type)) {
   512→					// 단위명
   513→					setName = ANALYZE_SET_UNIT;
   514→					setAnalyzedResult(result, term, ANALYZE_SET_UNIT, ANALYZE_SET_NORMAL, ANALYZE_SET_FINAL);
   515→				} else if (ProductNameTokenizer.COMPOUND.equals(type)) {
   516→					setName = ANALYZE_SET_COMPOUND;
   517→					setAnalyzedResult(result, term, ANALYZE_SET_COMPOUND, ANALYZE_SET_NORMAL, ANALYZE_SET_FINAL);
   518→				} else if (ProductNameTokenizer.STOPWORD.equals(type)) {
   519→					setName = ANALYZE_SET_STOPWORD;
   520→					setAnalyzedResult(result, term, ANALYZE_SET_STOPWORD);
   521→				} else {
   522→					// 일반단어
   523→					setName = ANALYZE_SET_NORMAL;
   524→					setAnalyzedResult(result, term, ANALYZE_SET_NORMAL, ANALYZE_SET_FINAL);
   525→				}
   526→
   527→				if ((synonyms = synAttr.getSynonyms()) != null && synonyms.size() > 0) {
   528→					wordList = result.get(ANALYZE_SET_SYNONYM);
   529→					wordList.add(words = new ArrayList<>());
   530→					words.add(term);
   531→					wordList = result.get(setName);
   532→					words2 = wordList.get(wordList.size() - 1);
   533→					oneWaySynonym = isOneWaySynonym(client, index, term);
   534→					synonymWayMap.put(term, oneWaySynonym);
   535→					synonymMap.put(term, words);
   536→					logger.trace("SYNONYM [{}] {} / {} / {}", setName, term, oneWaySynonym, synonyms);
   537→					for (CharSequence synonym : synonyms) {
   538→						String s = String.valueOf(synonym);
   539→						words.add(s);
   540→						if (!(ANALYZE_SET_NORMAL.equals(setName)
   541→							|| ANALYZE_SET_MODEL_NAME.equals(setName))) {
   542→							words2.add(s);
   543→						}
   544→						setAnalyzedResult(result, s, ANALYZE_SET_FINAL);
   545→					}
   546→				}
   547→
   548→				if (!ANALYZE_SET_FULL_STRING.equals(setName)) {
   549→					Iterator<String> iter = extAttr.iterator();
   550→					if (iter != null && iter.hasNext()) {
   551→						wordList = result.get(setName);
   552→						words = wordList.get(wordList.size() - 1);
   553→						while (iter.hasNext()) {
   554→							String s = iter.next();
   555→							logger.trace("EXT [{}] {} / {} / {} / {}", setName, term, s, words, wordList);
   556→							words.add(s);
   557→							setAnalyzedResult(result, s, ANALYZE_SET_NORMAL, ANALYZE_SET_FINAL);
   558→							synonyms = synAttr.getSynonyms();
   559→							if (synonyms != null && synonyms.size() > 0) {
   560→								oneWaySynonym = isOneWaySynonym(client, index, s);
   561→								synonymWayMap.put(s, oneWaySynonym);
   562→								synonymMap.put(term, words);
   563→								logger.trace("EXT-SYN [{}] {} / {} / {} / {} / {}", setName, term, s, oneWaySynonym, synonyms, wordList);
   564→								setAnalyzedResult(result, s, ANALYZE_SET_SYNONYM);
   565→								wordList = result.get(ANALYZE_SET_SYNONYM);
   566→								List<String> list = wordList.get(wordList.size() - 1);
   567→								for (CharSequence synonym : synonyms) {
   568→									s = String.valueOf(synonym);
   569→									list.add(s);
   570→									setAnalyzedResult(result, s, ANALYZE_SET_FINAL);
   571→								}
   572→							}
   573→						}
   574→					}
   575→				}
   576→				if(!ProductNameTokenizer.FULL_STRING.equals(type)){
   577→					tempTermList.add(term);
   578→				}
   579→			}
   580→			if(tempTermList.size() > 1){
   581→				for(String tempterm : tempTermList){
   582→					//현재 단어
   583→					setAnalyzeSynonym(synonymDict, tempterm, client, index, result, synonymWayMap, synonymMap, words, words2, wordList, setName, useForQuery);
   584→
   585→					//이전 텀 처리
   586→					if(prevTerm != null){
   587→						String combineTermTwo = prevTerm.concat(tempterm);
   588→						setAnalyzeSynonym(synonymDict, combineTermTwo, client, index, result, synonymWayMap, synonymMap, words, words2, wordList, setName, useForQuery);
   589→
   590→						//이전 + 이전텀 처리
   591→						if(prePrevTerm != null){
   592→							String combineTermThree = prePrevTerm.concat(combineTermTwo);
   593→							setAnalyzeSynonym(synonymDict, combineTermThree, client, index, result, synonymWayMap, synonymMap, words, words2, wordList, setName, useForQuery);
   594→						}
   595→					}
   596→					prePrevTerm = prevTerm;
   597→					prevTerm = tempterm;
   598→				}
   599→			}
   600→			logger.trace("SYNONYM-WAY : {}", synonymWayMap);
   601→		} catch (Exception e) {
   602→			logger.error("", e);
   603→		}
   604→	}
   605→	// 랭킹뷰어, 관리도구에서 사용되는 동의어 확장용 메소드
   606→	private static void setAnalyzeSynonym(SynonymDictionary dictionary, String combineTerm, NodeClient client, String index, Map<String, List<List<String>>> result, Map<String, Boolean> synonymWayMap,
   607→										  Map<String, List<String>> synonymMap, List<String> words, List<String> words2, List<List<String>> wordList, String setName, boolean useForQuery) {
   608→		CharSequence[] dictData = dictionary.get(new CharVector(combineTerm));
   609→		if(dictData != null){
   610→			List<CharSequence> synonyms = getAnalyzeSynonym(combineTerm, useForQuery);
   611→
   612→			if(synonyms.size() > 0){
   613→				wordList = result.get(ANALYZE_SET_SYNONYM);
   614→				wordList.add(words = new ArrayList<>());
   615→				words.add(combineTerm);
   616→				wordList = result.get(setName);
   617→				words2 = wordList.get(wordList.size() - 1);
   618→
   619→				boolean oneWaySynonym = isOneWaySynonym(client, index, combineTerm);
   620→				synonymWayMap.put(combineTerm, oneWaySynonym);
   621→				synonymMap.put(combineTerm, words);
   622→				for (CharSequence synonym : synonyms) {
   623→					String s = String.valueOf(synonym);
   624→					words.add(s);
   625→					if (!(ANALYZE_SET_NORMAL.equals(setName)
   626→							|| ANALYZE_SET_MODEL_NAME.equals(setName)
   627→							|| ANALYZE_SET_UNIT.equals(setName))) {
   628→						words2.add(s);
   629→					}
   630→					if(useForQuery){
   631→						setAnalyzedResult(result, s, ANALYZE_SET_FINAL);
   632→					}
   633→				}
   634→			}
   635→		}
   636→	}
