  1615→		boolean stopWord = request.paramAsBoolean("stopWord", true);
  1616→		boolean synonym = request.paramAsBoolean("synonym", true);
  1617→
  1618→		if (!GET.equals(request.method())) {
  1619→			jparam = parseRequestBody(request);
  1620→			index = jparam.optString("index", ES_DICTIONARY_INDEX);
  1621→			text = jparam.optString("text", "");
  1622→			stopWord = jparam.optBoolean("stopWord", true);
  1623→			synonym = jparam.optBoolean("synonym", true);
  1624→		}
  1625→
  1626→		TokenStream stream = null;
  1627→		try {
  1628→			stream = ProductNameAnalyzerProvider.getAnalyzer(text, true, synonym, stopWord, true, false);
  1629→			expansionKeyword(text, stream, writer);
  1630→		} finally {
  1631→			try { stream.close(); } catch (Exception ignore) { }
  1632→		}
  1633→	}
