  1766→	private void getSynonymListAction(RestRequest request, NodeClient client, JSONWriter writer){
  1767→		JSONObject jparam = new JSONObject();
  1768→		String keyword = "";
  1769→		boolean useForQuery = true;
  1770→		boolean useSynonym = true;
  1771→		boolean useStopword = false;
  1772→		boolean useFullString = true;
  1773→
  1774→		logger.debug("get-synonym-list start");
  1775→		if (!GET.equals(request.method())) {
  1776→			jparam = parseRequestBody(request);
  1777→			keyword = jparam.optString("keyword", "");
  1778→		} else {
  1779→			try{
  1780→				keyword = URLDecoder.decode(request.param("keyword", ""), "UTF-8");
  1781→			} catch (UnsupportedEncodingException e){
  1782→				logger.error("UnsupportedEncodingException Catched !!! >>>> \n" + e.getMessage());
  1783→				logger.debug("error >>> {}", e);
  1784→			}
  1785→		}
  1786→
  1787→		TokenStream stream = null;
  1788→		try {
  1789→			writer.key("query").value(keyword);
  1790→			writer.key("result").array();
  1791→			stream = ProductNameAnalyzerProvider.getAnalyzer(keyword, useForQuery, useSynonym, useStopword, useFullString, false);
  1792→			getSynonymList(keyword, stream, writer);
  1793→			writer.endArray();
  1794→			writer.key("success").value(true);
  1795→		} finally {
  1796→			try {
  1797→				stream.close();
  1798→			} catch (Exception ignore) {
  1799→				logger.debug("Exception >>> {}", ignore.getMessage());
  1800→			}
