  1804→	/**
  1805→	 * 동의어 리스트.
  1806→	 */
  1807→	public static void getSynonymList(String text, TokenStream stream, JSONWriter writer) {
  1808→		CharTermAttribute termAttr = stream.addAttribute(CharTermAttribute.class);
  1809→		TypeAttribute typeAttr = stream.addAttribute(TypeAttribute.class);
  1810→		SynonymAttribute synAttr = stream.addAttribute(SynonymAttribute.class);
  1811→		Map<String, List<List<String>>> result = new HashMap<>();
  1812→		List<CharSequence> synonyms = synAttr.getSynonyms();
  1813→
  1814→		for (String key : ANALYSIS_RESULT_LABELS.keySet()) {
  1815→			result.put(key, new ArrayList<>());
  1816→		}
  1817→
  1818→		String term = null;
  1819→		String type = null;
  1820→		String setName = null;
  1821→		try {
  1822→			stream.reset();
  1823→			while (stream.incrementToken()) {
  1824→				term = String.valueOf(termAttr);
  1825→				type = typeAttr.type();
  1826→				logger.trace("TERM:{} / {}", term, type);
  1827→				if (ProductNameTokenizer.FULL_STRING.equals(type)) {
  1828→					// 전체 단어
  1829→					setName = ANALYZE_SET_FULL_STRING;
  1830→					setAnalyzedResult(result, term, ANALYZE_SET_FULL_STRING, ANALYZE_SET_FINAL);
  1831→				} else if (ProductNameTokenizer.MODEL_NAME.equals(type)) {
  1832→					// 모델명의 경우 색인시와 질의시 추출방법이 서로 다르다.
  1833→					setName = ANALYZE_SET_MODEL_NAME;
  1834→					setAnalyzedResult(result, term, ANALYZE_SET_MODEL_NAME, ANALYZE_SET_FINAL);
  1835→				} else {
  1836→					// 일반단어
  1837→					setName = ANALYZE_SET_NORMAL;
  1838→					setAnalyzedResult(result, term, ANALYZE_SET_NORMAL, ANALYZE_SET_FINAL);
  1839→				}
  1840→
  1841→				if (!ANALYZE_SET_FULL_STRING.equals(setName)) {
  1842→					if ((synonyms = synAttr.getSynonyms()) != null && synonyms.size() > 0) {
  1843→						if (term.equals(text)) {
  1844→							for (CharSequence synonym : synonyms) {
  1845→								String s = String.valueOf(synonym);
  1846→								writer.value(s);
  1847→							}
  1848→						}
  1849→
  1850→					}
  1851→				}
  1852→			}
  1853→		} catch (Exception e) {
  1854→			logger.error("", e);
  1855→		}
  1856→	}
