   350→	public static void compileDictionary(NodeClient client, final DictionaryRepository repo,
   351→										 String filter, final boolean exportFile) {
   352→		if (baseFile == null || configFile == null) {
   353→			logger.error("DICTIONARY NOT LOADED!");
   354→		}
   355→
   356→		Set<String> filters = new HashSet<>();
   357→		if(filter != null){
   358→			String[] split = filter.trim().split(",");
   359→			for(String item : split){
   360→				filters.add(item.toLowerCase());
   361→			}
   362→		}
   363→		logger.info("Compile Dict types: {}", filters);
   364→
   365→		JSONObject dictProp = ResourceResolver.readYmlConfig(configFile);
   366→		JSONArray dictList = dictProp.optJSONArray(ATTR_DICTIONARY_LIST);
   367→		String basePath = dictProp.optString(ATTR_DICTIONARY_BASE_PATH);
   368→
   369→		for (int inx = 0; inx < dictList.length(); inx++) {
   370→			JSONObject row = dictList.optJSONObject(inx);
   371→			String dictionaryId = row.optString(ATTR_DICTIONARY_NAME);
   372→
   373→			// 필터가 존재하면서 dictionaryId가 없다면 스킵!
   374→			if (filters.size() > 0 && !filters.contains(dictionaryId)) {
   375→				continue;
   376→			}
   377→
   378→			//사전 한개를 로딩한다.
   379→//			SourceDictionary<?> sourceDictionary = compileDictionaryOne(repo, dictList, dictionaryId);
   380→			// 사전과 컴파일된 Count를 Map형태로 받는다.
   381→			Map<String, Object> compileDictMap = compileDictionaryOne(repo, dictList, dictionaryId);
   382→			SourceDictionary<?> sourceDictionary = (SourceDictionary) compileDictMap.get("dict");
   383→			if (sourceDictionary != null) {
   384→
   385→				// 엘라스틱서치에 .dsearch_dict_apply 인덱스에 upsert 한다.
   386→				SearchUtil.upsertData(client, ".dsearch_dict_apply", compileDictMap);
   387→
   388→				//파일로 기록. 컴파일.
   389→				if (exportFile) {
   390→					File dictFile = getDictionaryFile(baseFile, row, basePath);
   391→					OutputStream ostream = null;
   392→					try {
   393→						ostream = new FileOutputStream(dictFile);
   394→						sourceDictionary.writeTo(ostream);
   395→						logger.info("DICTIONARY FILE SAVED! {} / {}", dictionaryId, dictFile.getAbsolutePath());
   396→					} catch (Exception ignore) {
   397→					} finally {
   398→						try {
   399→							ostream.close();
   400→						} catch (Exception ignore) {
   401→						}
   402→					}
   403→				}
   404→			}
   405→		}
   406→		logger.debug("DICTIONARY LOAD COMPLETE! [{}]", filter == null ? "ALL" : filter);
   407→	}
