### 3.3 TransportNodesAction 구현

```java
// TransportReloadDictionaryAction.java
package com.danawa.search.analysis.product;

import com.danawa.search.analysis.dict.ProductNameDictionary;
import com.danawa.util.ContextStore;
import org.apache.logging.log4j.Logger;
import org.elasticsearch.action.ActionListener;
import org.elasticsearch.action.FailedNodeException;
import org.elasticsearch.action.support.ActionFilters;
import org.elasticsearch.action.support.nodes.TransportNodesAction;
import org.elasticsearch.cluster.node.DiscoveryNode;
import org.elasticsearch.cluster.service.ClusterService;
import org.elasticsearch.common.inject.Inject;
import org.elasticsearch.common.io.stream.StreamInput;
import org.elasticsearch.common.logging.Loggers;
import org.elasticsearch.tasks.Task;
import org.elasticsearch.threadpool.ThreadPool;
import org.elasticsearch.transport.TransportService;
import java.io.IOException;
import java.util.List;

public class TransportReloadDictionaryAction extends TransportNodesAction<
    NodesReloadDictionaryRequest,
    NodesReloadDictionaryResponse,
    NodeReloadDictionaryRequest,
    NodeReloadDictionaryResponse> {

    private static final Logger logger = Loggers.getLogger(TransportReloadDictionaryAction.class, "");
    private static final ContextStore contextStore = ContextStore.getStore(AnalysisProductNamePlugin.class);

    @Inject
    public TransportReloadDictionaryAction(
            ThreadPool threadPool,
            ClusterService clusterService,
            TransportService transportService,
            ActionFilters actionFilters) {
        super(
            ReloadDictionaryAction.NAME,
            clusterService,
            transportService,
            actionFilters,
            NodeReloadDictionaryRequest::new,
            threadPool.executor(ThreadPool.Names.MANAGEMENT)  // ES 9.x: GENERIC 대신 MANAGEMENT 사용
        );
    }

    @Override
    protected NodesReloadDictionaryResponse newResponse(
            NodesReloadDictionaryRequest request,
            List<NodeReloadDictionaryResponse> responses,
            List<FailedNodeException> failures) {
        return new NodesReloadDictionaryResponse(clusterService.getClusterName(), responses, failures);
    }

    @Override
    protected NodeReloadDictionaryRequest newNodeRequest(NodesReloadDictionaryRequest request) {
        return new NodeReloadDictionaryRequest(request);
    }

    @Override
    protected NodeReloadDictionaryResponse newNodeResponse(StreamInput in, DiscoveryNode node) 
        throws IOException {
        return new NodeReloadDictionaryResponse(in);
    }

    @Override
    protected NodeReloadDictionaryResponse nodeOperation(NodeReloadDictionaryRequest request, Task task) {
        long startTime = System.currentTimeMillis();
        DiscoveryNode localNode = clusterService.localNode();

        try {
            // 사전이 로드되어 있는지 확인
            ProductNameDictionary dictionary = contextStore.getAs(
                ProductNameDictionary.PRODUCT_NAME_DICTIONARY, 
                ProductNameDictionary.class
            );

            if (dictionary == null) {
                return new NodeReloadDictionaryResponse(
                    localNode, false, "Dictionary not loaded", 0, 0
                );
            }

            // 사전 타입별 reload 또는 전체 reload
            String dictType = request.getDictionaryType();
            if (dictType != null && !dictType.isEmpty()) {
                // 특정 사전만 reload (향후 구현)
                logger.info("Reloading dictionary type: {} on node: {}", 
                    dictType, localNode.getName());
            }

            // 전체 사전 reload
            ProductNameDictionary.reloadDictionary();

            long reloadTime = System.currentTimeMillis() - startTime;
            int dictSize = dictionary.size();

            logger.info("Dictionary reloaded successfully on node: {} in {}ms", 
                localNode.getName(), reloadTime);

            return new NodeReloadDictionaryResponse(
                localNode, true, "Reload successful", reloadTime, dictSize
            );

        } catch (Exception e) {
            logger.error("Failed to reload dictionary on node: " + localNode.getName(), e);
            return new NodeReloadDictionaryResponse(
                localNode, false, e.getMessage(), 
                System.currentTimeMillis() - startTime, 0
            );
        }
    }
}
```

### 3.4 REST Handler 구현

```java
// RestReloadDictionaryAction.java
package com.danawa.search.analysis.product;

import org.elasticsearch.client.internal.node.NodeClient;
import org.elasticsearch.rest.BaseRestHandler;
import org.elasticsearch.rest.RestRequest;
import org.elasticsearch.rest.RestResponse;
import org.elasticsearch.rest.RestStatus;
import org.elasticsearch.rest.action.RestToXContentListener;
import java.util.List;
import static org.elasticsearch.rest.RestRequest.Method.POST;

public class RestReloadDictionaryAction extends BaseRestHandler {

    @Override
    public String getName() {
        return "reload_dictionary_action";
    }

    @Override
    public List<Route> routes() {
        return List.of(
            new Route(POST, "/_analysis-product-name/reload-dict-cluster"),
            new Route(POST, "/_cluster/nodes/reload-dictionary")
        );
    }

    @Override
    protected RestChannelConsumer prepareRequest(RestRequest request, NodeClient client) {
        NodesReloadDictionaryRequest reloadRequest = new NodesReloadDictionaryRequest();

        // 요청 파라미터 파싱
        String dictType = request.param("type");
        boolean force = request.paramAsBoolean("force", false);

        reloadRequest.setDictionaryType(dictType);
        reloadRequest.setForceReload(force);

        // 특정 노드 지정 (선택적)
        String[] nodeIds = request.paramAsStringArray("node_id", null);
        if (nodeIds != null) {
            reloadRequest.nodesIds(nodeIds);
        }

        return channel -> client.execute(
            ReloadDictionaryAction.INSTANCE,
            reloadRequest,
            new RestToXContentListener<>(channel)
        );
    }
}
```

