// 무중단 갱신을 위한 Double-Buffering 패턴
public class DictionaryManager {
    private volatile ProductNameDictionary activeDictionary;
    private volatile ProductNameDictionary standbyDictionary;

    public synchronized void swapDictionaries() {
        ProductNameDictionary temp = activeDictionary;
        activeDictionary = standbyDictionary;
        standbyDictionary = temp;
    }

    public void loadToStandby(DictionaryRepository repo) {
        standbyDictionary = ProductNameDictionary.loadDictionary(baseFile, dictProp);
    }

    public ProductNameDictionary getActive() {
        return activeDictionary;
    }
}
